const FORMATS = [
  {id:"bamboo",n:"Vapeur Bamboo",st:"Vapeur Bamboo",s:["riz","pdtvap","quinoa"],p:["blanc","tofu","soyeux","mollets","pois"],v:["carotte","haricots","courgette","aubergine","potimarron","epinards","brocoli","panais","pakchoi","blettes","navet","patatedouce","fenouil","daikon","courgespaghetti","butternut"],k:2,d:1,
   sa:["oliveperslil","sesame","thym","bouillon"],x:[],
   mat:"une assiette creuse tiède" + G_TIEDE() + ". Le plat en deux mots : la cuisson vapeur douce. Tout cuit dans le panier du rice cooker avec seulement de l'eau et aucune matière grasse. On obtient des aliments très tendres et tièdes qui conviennent à un larynx irrité. La sauce et l'huile ne s'ajoutent qu'au dernier moment",
   core:"Les cycles vapeur. Les éléments cuisent en deux cycles qui se suivent, sans jamais ouvrir en cours de cuisson, car la vapeur s'échapperait et la chaleur retomberait. Premier cycle, de 20 à 30 minutes : les éléments dont l'étape indique « premier cycle vapeur » (les plus longs à cuire). Au bip, deuxième cycle, de 10 à 15 minutes : ceux dont l'étape indique « second cycle vapeur » (les plus tendres), ajoutés dans le panier au moment où l'on ouvre. Les morceaux reposent sur un papier sulfurisé percé, jamais directement sur le panier. Pendant que le dernier cycle tourne, préparer la sauce. Quand il se termine, ouvrir en éloignant le visage de la vapeur et laisser tiédir 5 minutes dans le panier ouvert. Repères : la vapeur reste régulière, sans gros bouillonnement, et l'appareil décompte les minutes. Point de contrôle : tous les éléments sont chauds à cœur et s'écrasent à la fourchette. À éviter : soulever le couvercle pour regarder en cours de cycle, qui prolonge la cuisson et la rend inégale",
   a:"Assiette creuse tiède. Dresser le féculent en dôme, c'est-à-dire en petit tas arrondi au centre. Poser les légumes en éventail à côté (côte à côte, légèrement décalés, comme un éventail déplié) et la protéine en appui contre le féculent, tranchée si elle est en morceaux. Napper d'un filet de sauce, c'est-à-dire verser la sauce en la laissant recouvrir légèrement le plat, sans le noyer.",
   fin:"Servir tiède, jamais brûlant : le chaud irrite le larynx. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Tous les éléments peuvent se cuire la veille ; le jour même, les réchauffer 5 min à la vapeur et préparer la sauce au dernier moment.",
   tip:"Un seul panier, deux cycles vapeur : c'est la force du Bamboo, et la vapeur ne demande ni surveillance ni matière grasse. L'huile se rajoute toujours en fin de préparation, sans être chauffée, pour rester douce."},
  {id:"slow",n:"Slow cook Bamboo",st:"Slow cook Bamboo",s:["pdtvap","riz","quinoa"],p:["effile"],v:["carotte","haricots","courgette","potimarron","panais","epinards","brocoli","navet","celerirave","patatedouce","blettes","butternut"],k:2,d:1,
   sa:["oliveperslil","thym","bouillon"],x:[],
   mat:"une assiette creuse tiède" + G_TIEDE() + ". Le plat en deux mots : du poulet cuit très doucement pendant deux heures dans un peu d'eau chaude. Il devient si tendre qu'il se défait en fibres sous la fourchette : on dit qu'il est effiloché. Servi avec ses accompagnements tièdes",
   core:"Le montage de la cuve. Le poulet cuit seul dans la cuve, avec 250 ml d'eau chaude, pendant 2 heures en mode SLOW COOK (durée minimale de ce programme, réglable de 2 à 8 heures), sans ouvrir. Le Bamboo ne fait qu'une cuisson à la fois : cuire donc le féculent et les légumes à part, avant ou après le poulet, à la vapeur dans la cuve rincée, suivant les étapes ci-dessus. Au moment du repas, réchauffer doucement l'ensemble 5 minutes à la vapeur et mélanger le poulet effiloché aux autres éléments tièdes. Repères : une odeur douce monte et un léger bruissement se fait entendre sous le couvercle. Point de contrôle : la chair s'effiloche sans aucune résistance et reste humide. À éviter : ouvrir le couvercle avant la fin, qui fait retomber la chaleur et prolonge la cuisson",
   a:"Assiette creuse tiède. Féculent et légumes légèrement écrasés à la fourchette à gauche, effiloché en petit dôme (petit tas arrondi) à droite, puis un filet de sauce sur l'ensemble, versé doucement pour napper (recouvrir légèrement) sans noyer le plat.",
   fin:"Servir tiède. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Le plat entier se cuit la veille et se garde 2 jours en boîte en verre au frigo. La sauce se prépare au dernier moment.",
   tip:"Le poulet reste moelleux parce qu'il cuit à la vapeur douce, sans jamais bouillir : c'est ce qui le garde tendre et facile à avaler. Si les fibres sont un peu sèches, l'humecter d'une cuillère de liquide de cuisson."},
  {id:"cocon",n:"Cocon purée",st:"Cocon & purées",s:["puree"],p:["blanc","effile","mollets","soyeux"],v:["carotte","potimarron","panais","butternut","brocoli","epinards","navet","patatedouce","blettes","courgespaghetti","celerirave"],k:1,d:1,
   sa:["oliveperslil","thym","bouillon"],x:[],
   mat:G_PRESSE + ", une assiette creuse tiède" + G_TIEDE() + ", une fourchette. Le plat en deux mots : un « cocon » de purée. C'est un nid de purée tiède et très douce dans lequel on pose la protéine et les légumes écrasés. Un plat réconfortant qui passe sans effort quand la gorge est sensible",
   core:"L'écrasement. Écraser grossièrement le légume cuit à la fourchette dans un bol, puis le mélanger à la purée, à la cuillère, en soulevant la masse plutôt qu'en la battant. Si le mélange est trop ferme, ajouter une cuillère d'eau chaude prise dans la cuve du Bamboo. Repères : la purée devient lisse et brillante. Point de contrôle : elle se tient en nid sur la cuillère sans couler. À éviter : mixer ou battre trop longtemps, elle devient élastique et collante",
   a:"Assiette creuse tiède. Faire un nid de purée au centre en creusant le milieu avec le dos d'une cuillère, poser la protéine dedans (en lamelles, en dés ou coupée en deux, selon la protéine), puis napper d'un filet de sauce, c'est-à-dire la verser en la laissant recouvrir légèrement.",
   fin:"Servir tiède. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"L'huile s'ajoute au service, sans être chauffée, et la sauce se prépare au dernier moment.",
   tip:"Une purée tiède est le meilleur ami d'un larynx irrité : douce, chaude sans être brûlante. Avec la vapeur, elle reste moelleuse sans beurre ni crème."},
  {id:"fraicheur",n:"Salade tiède",st:"Fraîcheur tiède",s:["pdtvap","quinoa"],p:["oeufs","mollets","blanc","tofu","soyeux"],v:["haricots","carotte","courgette","brocoli","potimarron","pakchoi","blettes","daikon","epinards","courgespaghetti","fenouil"],k:2,d:1,
   sa:["oliveperslil","sesame","thym"],x:[],
   mat:"un saladier, deux cuillères pour mélanger, une assiette creuse tiède" + G_TIEDE() + ". Le plat en deux mots : une salade composée dont tous les éléments sont cuits, puis servis tièdes, ni chauds ni glacés. Elle est assaisonnée d'une sauce légère. C'est l'esprit d'une salade, mais sans aucun élément à croquer",
   core:"L'assaisonnement tiède. Laisser tiédir les éléments cuits 10 minutes : le plat se sert tiède, pas glacé. Enrober le féculent de la moitié de la sauce, c'est-à-dire le tourner dans le saladier pour que chaque morceau soit recouvert d'une fine couche, puis ajouter les légumes et mélanger délicatement avec les deux cuillères, en soulevant sans écraser. Repères : la sauce enrobe sans détremper. Point de contrôle : tout est tiède au toucher et rien n'est écrasé. À éviter : sortir le plat froid du frigo, car le froid irrite le larynx",
   a:"Assiette creuse tiède. Disposer le féculent en couronne, c'est-à-dire en cercle autour de l'assiette, les légumes en éventail (côte à côte, légèrement décalés) par-dessus, et la protéine au centre. Napper du reste de la sauce en filet.",
   fin:"Si la sauce est déjà bue par le féculent, rajouter un filet d'huile, sans la chauffer. Servir tiède. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Les éléments se cuisent la veille (2 jours en verre) ; l'assemblage se fait au dernier moment, tiède.",
   tip:"Un plat tiède est bien plus doux pour le larynx qu'une salade froide : ici tout est cuit et rien n'est croquant. Sortir les éléments du frigo 10 minutes avant de les assembler."},
  {id:"bol",n:"Bol tiède",st:"Vapeur Bamboo",s:["riz","quinoa","soba"],p:["blanc","effile","tofu","soyeux","mollets","pois"],v:["carotte","haricots","aubergine","courgette","potimarron","epinards","brocoli","pakchoi","blettes","daikon","patatedouce","courgespaghetti","butternut"],k:2,d:1,
   sa:["oliveperslil","sesame","thym","bouillon"],x:[],
   mat:"un bol large tiède" + G_TIEDE(1) + ". Le plat en deux mots : tout dans un seul bol. Le féculent au fond, les garnitures rangées en quartiers bien nets, comme les parts d'un gâteau, et la protéine au centre. Un repas complet que l'on mange à la cuillère ou à la fourchette",
   core:"L'assemblage du bol. Réchauffer le féculent 5 minutes à la vapeur dans le panier, puis préparer les quartiers de garniture : chaque légume garde sa place, bien séparé des autres, pour garder ses couleurs. Repères : la vapeur est douce. Point de contrôle : le bol est tiède sur toute sa hauteur, du fond à la surface. À éviter : un bol bouillant, qui irrite le larynx",
   a:"Bol large tiède. Mettre le féculent au fond en dôme aplati, ranger les garnitures en quartiers nets tout autour, poser la protéine au centre, puis verser la sauce en zigzag, c'est-à-dire en filet fin qui va et vient d'un bord à l'autre.",
   fin:"Donner un dernier filet d'huile, sans la chauffer, et servir tiède. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Féculent, légumes et protéine se préparent la veille (2 jours en verre) ; le bol se monte à la minute.",
   tip:"Tailler chaque garniture de la même taille et la ranger en quartiers donne un bol digne d'un restaurant. Chaque légume garde sa couleur parce qu'il n'est pas mélangé aux autres."}  ,
  {id:"bibimbap",n:"Bibimbap doux",st:"Fraîcheur tiède",s:["riz"],p:["tofu","mollets"],v:["carotte","epinards","pakchoi","blettes","daikon","courgette","haricots","courgespaghetti"],k:2,d:1,
   sa:["sojasesame","misodoux"],x:[["graines de sésame",1,"c. à café"],["nori",1,"pièce"]],herbs:["ciboulette","coriandre","persil"],
   mat:"un bol large tiède" + G_TIEDE(1) + ", de petits bols pour chaque légume, " + G_CISEAUX + ". Le plat en deux mots : le bibimbap est un plat coréen dont le nom veut dire « riz mélangé ». C'est un bol de riz couvert de légumes cuits séparément, d'une protéine et d'une sauce, que l'on mélange soi-même à table. Cette version est douce : sans épices fortes",
   core:"Les légumes séparés. Cuire chaque légume à la vapeur sans le mélanger aux autres : les ranger en tas distincts sur le papier sulfurisé, en séparant les tas par une barrière de papier replié ou par de petits bols posés sur le panier, pour que les couleurs et les goûts restent bien distincts. Repères : chaque légume garde son parfum et sa teinte. Point de contrôle : tous sont tièdes et fondants. À éviter : tout mélanger avant de dresser, car on perd la beauté du plat",
   a:"Bol large tiède. Mettre le riz au fond en dôme aplati, ranger les légumes en quartiers de couleurs tout autour, poser la protéine au centre, puis émietter le nori sur le dessus : le nori est une algue séchée en feuille fine et noire, au goût de mer, que l'on coupe aux ciseaux ou émiette avec les doigts.",
   fin:"Parsemer de graines de sésame et servir la sauce à part, dans son petit bol. À table, mélanger de bas en haut avec la cuillère, pour que le riz s'imprègne de tous les parfums. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Les légumes et le riz se préparent la veille ; le bol se monte à la minute et la sauce se prépare au dernier moment.",
   tip:"Mélanger à table, de bas en haut : c'est le geste qui donne son nom au plat. Chaque bouchée a alors un peu de tous les goûts."},
  {id:"soba",n:"Soba tièdes",st:"Fraîcheur tiède",s:["soba"],p:["tofu","mollets","blanc"],v:["carotte","pakchoi","daikon","epinards","courgette","blettes","courgespaghetti"],k:2,d:1,
   sa:["sojasesame","misodoux"],x:[["graines de sésame",1,"c. à café"],["nori",1,"pièce"]],herbs:["ciboulette","coriandre","persil"],
   mat:"un bol large tiède" + G_TIEDE(1) + ", des baguettes ou une fourchette, " + G_CISEAUX + ". Le plat en deux mots : des nouilles japonaises de sarrasin, les soba, servies ici tièdes. Au Japon, on les sert souvent froides, mais le froid irrite le larynx. Elles sont garnies de légumes cuits, d'une protéine et d'une sauce légère",
   core:"L'assaisonnement. Enrober les soba tièdes de la moitié de la sauce, c'est-à-dire les tourner délicatement dans un grand bol pour que chaque nouille soit recouverte d'une fine couche. Ajouter les légumes cuits tièdes en filets, puis la protéine. Repères : les nouilles brillent sans baigner. Point de contrôle : tout est tiède au toucher. À éviter : servir glacé comme des soba froides, car le froid irrite le larynx",
   a:"Bol large tiède. Mettre les soba en nid au centre, poser la protéine sur le dessus, les légumes tout autour, puis couper le nori aux ciseaux en rubans fins de 3 mm : le nori est une algue séchée en feuille fine et noire, au goût de mer.",
   fin:"Napper du reste de la sauce, en filet, et parsemer de graines de sésame. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Les soba, les légumes et la sauce se préparent la veille ; le bol se monte à la minute.",
   tip:"Rincées à l'eau tiède, les soba gardent un goût de noisette et restent souples. Si elles collent au moment de servir, les passer quelques secondes sous l'eau tiède."},
  {id:"misosoupe",n:"Soupe-repas miso",st:"Cocon & purées",s:["riz","soba"],p:["soyeux","mollets"],v:["pakchoi","epinards","daikon","carotte","courgette","blettes","courgespaghetti"],k:2,d:1,
   sa:["sojasesame"],x:[["miso blanc",1,"c. à café"],["wakamé",3,"g"],["eau",350,"ml"]],herbs:["ciboulette","persil"],
   mat:"une casserole, un bol profond tiède" + G_TIEDE(1) + ", une louche. Le plat en deux mots : une soupe japonaise légère et parfumée, assez copieuse pour faire un repas. On y trouve le féculent, la protéine et les légumes dans un bouillon doux, parfumé au miso, une pâte de soja fermenté qui donne le goût salé et profond",
   core:"Le bouillon miso. Mettre le wakamé (une algue brune séchée) dans le petit bol, le recouvrir d'eau tiède et le laisser 5 minutes : il gonfle plusieurs fois son volume et devient souple, on dit qu'il se réhydrate. L'égoutter. Porter l'eau à frémissement dans la casserole (de petites bulles régulières, sans gros bouillons), puis ajouter le wakamé réhydraté, les légumes cuits et la protéine, et laisser 2 minutes à feu très doux. Hors du feu, délayer le miso : le mettre dans la louche, verser dessus un peu de bouillon et l'écraser avec le dos d'une cuillère jusqu'à ce qu'il soit lisse, puis le remettre dans la casserole en remuant. Repères : le bouillon est ambré et fume doucement. Point de contrôle : tiède-chaud, jamais bouillant. À éviter : faire bouillir le miso, il perd son parfum",
   a:"Bol profond tiède. Mettre le féculent au fond, poser la protéine et les légumes par-dessus, puis verser le bouillon à la louche, doucement, pour ne pas faire de remous.",
   fin:"Laisser reposer la soupe 3 minutes avant de la manger : elle se sert tiède. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Le bouillon se prépare la veille sans miso ; le miso se délaye à la minute, hors du feu.",
   tip:"Le miso ne bout jamais : on le délaye hors du feu pour garder tout son parfum. Si le bouillon a refroidi, le réchauffer doucement sans le faire bouillir, puis y remettre le miso."},
  {id:"japchae",n:"Japchae doux",st:"Fraîcheur tiède",s:["vermicelles"],p:["tofu","blanc"],v:["carotte","epinards","pakchoi","blettes","courgette","daikon"],k:2,d:2,
   sa:["sojasesame"],x:[["graines de sésame",1,"c. à café"]],herbs:["ciboulette","coriandre"],
   mat:"un grand saladier, " + G_CISEAUX + ", une assiette creuse tiède" + G_TIEDE() + ". Le plat en deux mots : le japchae est un plat coréen de nouilles transparentes mélangées à des légumes, à une protéine et à une sauce parfumée. Traditionnellement, les nouilles et les légumes sont poêlés ; ici, rien n'est poêlé : tout est cuit à la vapeur et mélangé tiède",
   core:"Le mélange tiède. Dans un grand saladier, mélanger délicatement les vermicelles tièdes, les légumes cuits à la vapeur et la protéine avec la sauce, en soulevant à deux mains ou avec deux cuillères, comme pour aérer une salade. Repères : les vermicelles brillent et prennent la couleur de la sauce. Point de contrôle : tout est tiède et bien enrobé, c'est-à-dire recouvert d'une fine couche de sauce. À éviter : trop mélanger, les légumes se délitent",
   a:"Assiette creuse tiède. Dresser en nid, c'est-à-dire en tas arrondi légèrement creusé au milieu, avec les légumes colorés sur le dessus.",
   fin:"Parsemer de graines de sésame, puis laisser reposer 2 minutes : les vermicelles boivent la sauce. L'herbe fraîche se prépare juste avant de servir et se répand en pluie fine, du bout des doigts, sur le plat.",
   orga:"Se prépare la veille et se réchauffe 5 min à la vapeur, avant d'être de nouveau mélangé avec la sauce.",
   tip:"Les vermicelles de patate douce restent souples même tièdes, sans coller, à condition d'être bien rincés et mélangés à la sauce tout de suite."}

];
/* ponctuation : chaque bloc de texte se termine par un point avant le suivant (« Repères : … », « À éviter : … ») */
const G_DOT = x => String(x).replace(/\s*\.?\s*$/, ".");
Object.keys(PROTEINS).forEach(k => { PROTEINS[k].cook = G_DOT(PROTEINS[k].cook); });
Object.keys(STARCHES).forEach(k => { STARCHES[k].cook = G_DOT(STARCHES[k].cook); });
Object.keys(VEGS).forEach(k => { VEGS[k].cook = G_DOT(VEGS[k].cook); });
FORMATS.forEach(f => { f.core = G_DOT(f.core); });
